#pragma once

// Deterministic, nonstandard inverse-source benchmark for CPSO performance studies.
// A spatially discretized 1D reaction-diffusion equation is advanced with RK4.
// The unknown parameters are source amplitudes; synthetic observations are
// generated by a known source. Linearity permits evaluating the difference
// state directly: both candidate and reference would use the same solver.
// This is a controlled computational-cost example, NOT a standardized BBOB
// objective nor evidence from real measurements.

#include <cmath>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <vector>

namespace cpso {

[[nodiscard]] inline double evaluate_inverse_diffusion_benchmark(
    const std::vector<double>& parameters, const std::uint64_t integration_steps) {
    constexpr double pi = 3.141592653589793238462643383279502884;
    constexpr std::uint64_t max_steps = 100'000U;
    if (parameters.empty()) {
        throw std::invalid_argument("inverse_diffusion requires dimension >= 1");
    }
    if (integration_steps < 16U || integration_steps > max_steps || integration_steps % 4U != 0U) {
        throw std::invalid_argument(
            "inverse_diffusion work_iterations must be a multiple of 4 in [16,100000]");
    }
    const std::size_t d = parameters.size();
    std::vector<double> source(d), u(d, 0.0), k1(d), k2(d), k3(d), k4(d), tmp(d);
    double regularizer = 0.0;
    for (std::size_t j = 0; j < d; ++j) {
        if (!std::isfinite(parameters[j])) {
            throw std::invalid_argument("inverse_diffusion received non-finite parameters");
        }
        const double truth = 0.4 * std::sin(2.0 * pi * static_cast<double>(j + 1U)
                                             / static_cast<double>(d + 1U));
        source[j] = std::tanh(parameters[j]) - std::tanh(truth);
        const double delta = parameters[j] - truth;
        regularizer += delta * delta;
    }
    // Diffusion and linear reaction remain stable for the requested RK4 range.
    // Neumann (zero-flux) boundary conditions use the endpoint itself as its
    // missing neighbor. Integration time is fixed as steps vary.
    constexpr double final_time = 2.0;
    constexpr double diffusion = 0.2;
    const double h = final_time / static_cast<double>(integration_steps);
    const auto derivative = [&](const std::vector<double>& state,
                                std::vector<double>& out, const double time) {
        const double forcing = 1.0 + 0.2 * std::sin(2.0 * pi * time);
        for (std::size_t j = 0; j < d; ++j) {
            const double left = j == 0U ? state[j] : state[j - 1U];
            const double right = j + 1U == d ? state[j] : state[j + 1U];
            const double decay = 1.1 + 0.02 * static_cast<double>(j % 11U);
            out[j] = -decay * state[j]
                + diffusion * (left - 2.0 * state[j] + right)
                + forcing * source[j];
        }
    };

    double observations_sum_sq = 0.0;
    for (std::uint64_t step = 0; step < integration_steps; ++step) {
        const double t = h * static_cast<double>(step);
        derivative(u, k1, t);
        for (std::size_t j = 0; j < d; ++j) tmp[j] = u[j] + 0.5 * h * k1[j];
        derivative(tmp, k2, t + 0.5 * h);
        for (std::size_t j = 0; j < d; ++j) tmp[j] = u[j] + 0.5 * h * k2[j];
        derivative(tmp, k3, t + 0.5 * h);
        for (std::size_t j = 0; j < d; ++j) tmp[j] = u[j] + h * k3[j];
        derivative(tmp, k4, t + h);
        for (std::size_t j = 0; j < d; ++j) {
            u[j] += (h / 6.0) * (k1[j] + 2.0 * k2[j] + 2.0 * k3[j] + k4[j]);
        }
        if ((step + 1U) % (integration_steps / 4U) == 0U) {
            for (const double residual : u) observations_sum_sq += residual * residual;
        }
    }
    return observations_sum_sq / (4.0 * static_cast<double>(d))
         + 0.001 * regularizer / static_cast<double>(d);
}

}  // namespace cpso
